const size_t kSubsetGlyphsCount = sizeof(kSubsetGlyphs) / sizeof(kSubsetGlyphs[0]);

const SubsetGlyph* getSubsetGlyph(uint16_t unicode) {
    int low = 0;
    int high = (int)kSubsetGlyphsCount - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (kSubsetGlyphs[mid].unicode == unicode) {
            return &kSubsetGlyphs[mid];
        }
        if (kSubsetGlyphs[mid].unicode < unicode) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return nullptr;
}
